// Tab completion for a GOQL where_expr: what could go at the cursor.
//
// A line-for-line port of gramps-object-query-language's
// completion.complete_from_vocabularies(), run over the same vocabulary
// data (data/goqlVocabulary.json, generated by
// scripts/export-goql-vocabulary.py from the installed GOQL). Keeping it a
// straight port, rather than a TS-flavored rewrite, is what lets
// __tests__/goqlCompletionCases.json -- copied from GOQL by that same
// script -- check both implementations against one set of cases. A
// behavior change belongs in GOQL first, then here.
//
// Never parses the whole expression (a half-typed one rarely parses); it
// only looks at the dotted path ending at the cursor and the token before it:
// - no dot: what fits the grammar position. Start of a condition (or after
//   `(` `,` `and` `or` `not` `if`): names, functions, `not`, Env. After a
//   complete operand: comparisons, and/or/in/is/not, for/if inside
//   parentheses. After a comparison or in/is: a value -- names, literals,
//   Date, constant classes, Env -- or, when the compared field holds a
//   class's constants (`type.value ==`), just that class (`EventType.`)
//   and then only its fitting constants (`date.modifier == Date.` -> MOD_*);
//   a true/false field gets True/False, a text field `"` (names once a
//   letter is typed)
// - Env only when the caller passes env names
// - inside a function call, its argument's role: Date( -> `"` only,
//   like( -> a field path, exists( -> a collection, len( / `for e in` ->
//   something iterable, `gender in` -> `[` or Env
// - `list_field[`: `0`; `[` after anything that isn't a list: nothing
// - a half-typed comparison (`gender <`): the operators it can become
// - `ClassName.`: that class's constants; `Env.`: the caller's env names
// - any other path: walked through relationships (`birth.`), JSON fields
//   (`primary_name.surname_list[0].`) and comprehension variables (`e.` in
//   `any(... for e in events)`)
// - inside a string literal, or after anything it can't follow: nothing.
import vocabularyData from "../data/goqlVocabulary.json";

export interface ValueConstants {
  /** The constant class, e.g. "EventType". */
  class: string;
  /** Only its constants starting with this, e.g. "MOD_" for a date's
   * modifier; "" for all. */
  prefix: string;
}

export interface FieldNode {
  type: string | string[] | null;
  fields?: Record<string, FieldNode>;
  items?: FieldNode;
  /** An integer that holds one of a class's ClassName.CONST values. */
  constants?: ValueConstants;
}

export interface Vocabulary {
  namespace: string;
  columns: string[];
  /** Each column's JSON type: "string", "boolean" or "integer". */
  column_types: Record<string, string>;
  fields: Record<string, FieldNode>;
  relationships: Record<string, string>;
  collections: Record<string, string | null>;
  keywords: string[];
  functions: string[];
  operators: string[];
  constants: Record<string, string[]>;
  env: string;
}

export type CompletionKind =
  | "column"
  | "field"
  | "relationship"
  | "collection"
  | "keyword"
  | "function"
  | "operator"
  | "constant_class"
  | "constant"
  | "env"
  | "variable"
  /** `"` to start a string, `[` to start a list. */
  | "punctuation"
  /** `0` inside a list field's `[`. */
  | "index";

export interface Completion {
  name: string;
  kind: CompletionKind;
  /** A field's JSON type, a relationship's or collection's target type,
   * a constant's class, or null. */
  detail: string | string[] | null;
  /** Replacing source.slice(start, cursor) with `name` applies it. */
  start: number;
}

export const GOQL_VOCABULARIES = (vocabularyData as unknown as { vocabularies: Record<string, Vocabulary> })
  .vocabularies;

const NAME = "[A-Za-z_][A-Za-z0-9_]*";
// One `[...]` after a name: a number (`[0]`), or a quoted type name
// (`attribute_list['Age']`, the first entry of that type).
const INDEX = `\\[(?:[0-9]+|'[^'\\\\]*'|"[^"\\\\]*")\\]`;
const SEGMENT = `${NAME}(?:${INDEX})*`;
const CHAIN = `${SEGMENT}(?:\\.${SEGMENT})*`;
// The lookbehind keeps a chain from starting partway through a name,
// number or `x[0]`/`f()` -- `1.5` or `f().x` don't complete.
const AT_CURSOR_RE = new RegExp(`(?<![A-Za-z0-9_.\\])])(?:(${CHAIN})\\.)?(${NAME})?$`);
const SEGMENT_RE = new RegExp(`(${NAME})((?:${INDEX})*)`, "g");
const INDEX_RE = new RegExp(INDEX, "g");
const BINDING_RE = new RegExp(`\\bfor\\s+(${NAME})\\s+in\\s+(${CHAIN})`, "g");
const PARTIAL_OPERATOR_RE = /[=!<>]+$/;
// The path a value is being written for: `path ==` (any comparison) or
// `path in [..., ` (a list of values, `not in` too).
const COMPARED_RE = new RegExp(`(?<![A-Za-z0-9_.\\])])(${CHAIN})\\s*(?:==|!=|<=|>=|<|>)\\s*$`);
const LISTED_RE = new RegExp(`(?<![A-Za-z0-9_.\\])])(${CHAIN})\\s+(?:not\\s+)?in\\s*\\[[^\\[\\]]*$`);
const INDEXED_RE = new RegExp(`(?<![A-Za-z0-9_.\\])])(${CHAIN})\\[$`);
// After a list comprehension taken by index: `[...][0].` then a path and a
// (possibly empty) word -- and `[...][`, its index.
const PICKED_RE = new RegExp(`\\]\\[[0-9]+\\]((?:\\.${SEGMENT})*)\\.(${NAME})?$`);
const PICK_INDEX_RE = /\]\[$/;
// A comprehension's own text: what it collects, then `for x in`.
const COMPREHENSION_RE = new RegExp(`^\\s*(${CHAIN})\\s+for\\s+${NAME}\\s+in\\b`);
const TOKEN_RE = new RegExp(
  "\\s+" +
    "|(?<string>'(?:\\\\.|[^'\\\\])*'|\"(?:\\\\.|[^\"\\\\])*\")" +
    "|(?<number>[0-9]+(?:\\.[0-9]+)?)" +
    `|(?<name>${NAME})` +
    "|(?<operator>==|!=|<=|>=|<|>)" +
    "|(?<other>[\\s\\S])",
  "g",
);

// What the grammar expects at the cursor, from the tokens before the word
// being typed -- see expected() and GOQL's completion.py for each one.
type Expected =
  | "operand"
  | "number"
  | "operator"
  | "value"
  | "is_value"
  | "not_in"
  | "in_list"
  | "path"
  | "string"
  | "collection"
  | "iterable"
  | "literal"
  | "index"
  | "nothing";
const OPERAND_AFTER = new Set(["and", "or", "not", "if"]);
const LITERALS = ["None", "True", "False"];
const CONTINUATIONS = ["and", "or", "in", "is", "not"];
const COMPREHENSION_WORDS = ["for", "if"];
const VALUE_FUNCTIONS = ["Date"];
const NON_OPERAND_WORDS = new Set(["and", "or", "not", "in", "is", "for", "if"]);
// What each argument of a whitelisted function call is: Date('Jan 1,
// 1968'), like(path, 'pattern'), exists(collection, condition),
// len([... for x in collection]), len(distinct([...])) or len(path);
// any(...) takes conditions.
const ARGUMENT_ROLES: Record<string, Expected[]> = {
  Date: ["string"],
  like: ["path", "string"],
  regex: ["path", "string"],
  exists: ["collection", "operand"],
  count: ["collection", "operand"],
  len: ["iterable"],
  distinct: ["iterable"],
  any: ["operand", "operand"],
};
// Roles whose argument is complete after one operand: only , or ) follows.
const SINGLE_TOKEN_ROLES = new Set<Expected>(["string", "path", "collection", "iterable"]);

type Token = [kind: string, text: string];

/** Each token in `text`, whitespace dropped. */
function tokens(text: string): Token[] {
  const out: Token[] = [];
  for (const m of text.matchAll(TOKEN_RE)) {
    const kind = Object.entries(m.groups ?? {}).find(([, v]) => v !== undefined)?.[0];
    if (kind) out.push([kind, m[0]]);
  }
  return out;
}

function endsOperand(token: Token | null): boolean {
  if (!token) return false;
  const [kind, text] = token;
  if (kind === "string" || kind === "number") return true;
  if (kind === "name") return !NON_OPERAND_WORDS.has(text);
  return text === ")" || text === "]";
}

function isWord(token: Token | null, word: string): boolean {
  return !!token && token[0] === "name" && token[1] === word;
}

/** One open ( or [: the function it calls (if any), which argument the
 * cursor is on, and whether it's a `path in [...]` list. */
interface Frame {
  bracket: string;
  fn: string | null;
  values: boolean;
  /** `path[`: an index into a list field. */
  subscript: boolean;
  argument: number;
}

function frameRole(frame: Frame): Expected | null {
  if (frame.fn === null) return null;
  const roles = ARGUMENT_ROLES[frame.fn] ?? [];
  return frame.argument < roles.length ? roles[frame.argument] : "nothing";
}

/** The brackets still open at the end of `toks`, outermost first. */
function openFrames(toks: Token[]): Frame[] {
  const frames: Frame[] = [];
  toks.forEach(([kind, text], i) => {
    if (kind !== "other") return;
    const previous = i > 0 ? toks[i - 1] : null;
    if (text === "(") {
      const fn = previous && previous[0] === "name" && !NON_OPERAND_WORDS.has(previous[1]) ? previous[1] : null;
      frames.push({ bracket: "(", fn, values: false, subscript: false, argument: 0 });
    } else if (text === "[") {
      // `path[` indexes a list; `in [` starts a list of values; any other
      // `[` starts a comprehension (`len([... for ...])`).
      frames.push({ bracket: "[", fn: null, values: isWord(previous, "in"), subscript: endsOperand(previous), argument: 0 });
    } else if ((text === ")" || text === "]") && frames.length) {
      frames.pop();
    } else if (text === "," && frames.length) {
      frames[frames.length - 1].argument++;
    }
  });
  return frames;
}

/** What the grammar expects after `text`, and whether a comprehension's
 * for/if could come there. */
function expected(text: string): [Expected, boolean] {
  const toks = tokens(text);
  const frames = openFrames(toks);
  const comprehension = frames.some((f) => f.fn === "any" || (f.bracket === "[" && !f.values && !f.subscript));
  const top = frames.length ? frames[frames.length - 1] : null;
  if (toks.length === 0) return ["operand", comprehension];
  const last = toks[toks.length - 1];
  const previous = toks.length > 1 ? toks[toks.length - 2] : null;
  const beforePrevious = toks.length > 2 ? toks[toks.length - 3] : null;
  if (last[0] === "other" && (last[1] === "(" || last[1] === "[" || last[1] === ",")) {
    if (!top) return ["nothing", comprehension];
    if (top.subscript) return [last[1] === "[" ? "index" : "nothing", comprehension];
    if (top.values) return ["literal", comprehension];
    if (top.bracket === "(" && top.fn !== null) return [frameRole(top) ?? "operand", comprehension];
    return [top.argument === 0 ? "operand" : "nothing", comprehension];
  }
  if (isWord(last, "not")) {
    if (endsOperand(previous)) return ["not_in", comprehension];
    if (isWord(previous, "is")) return ["value", comprehension];
    return ["operand", comprehension];
  }
  if (isWord(last, "is")) return ["is_value", comprehension];
  if (isWord(last, "for")) return ["nothing", comprehension];
  if (isWord(last, "in")) {
    if (isWord(beforePrevious, "for")) return ["iterable", comprehension];
    if (previous && previous[0] === "string") return ["path", comprehension];
    return ["in_list", comprehension];
  }
  if (last[0] === "name" && OPERAND_AFTER.has(last[1])) return ["operand", comprehension];
  // After an arithmetic operator: something with a numeric value.
  if (last[0] === "other" && "+-*/".includes(last[1])) return ["number", comprehension];
  if (last[0] === "operator") return ["value", comprehension];
  if (endsOperand(last)) {
    if (top && (top.values || top.subscript || SINGLE_TOKEN_ROLES.has(frameRole(top) as Expected))) {
      return ["nothing", comprehension];
    }
    return ["operator", comprehension];
  }
  return ["nothing", comprehension];
}

/** The constants the value being written at the end of `text` takes,
 * from the field it's compared with (`type.value ==` -> EventType), or
 * null. */
function valueConstants(
  vocabs: Vocabs,
  namespace: string,
  text: string,
  bindings: Map<string, Context | null>,
): ValueConstants | null {
  return comparedField(vocabs, namespace, text, bindings)?.constants ?? null;
}

/** The field a value being written at the end of `text` is compared with
 * (`surname ==`, `type.value in [...`), or null. */
function comparedField(
  vocabs: Vocabs,
  namespace: string,
  text: string,
  bindings: Map<string, Context | null>,
): FieldNode | null {
  const match = COMPARED_RE.exec(text) ?? LISTED_RE.exec(text);
  if (!match) return null;
  const context = walk(vocabs, namespace, segments(match[1]), bindings);
  return context && context.kind === "field" ? context.node : null;
}

function hasType(type: Completion["detail"], wanted: string): boolean {
  return type === wanted || (Array.isArray(type) && type.includes(wanted));
}

function isArray(type: Completion["detail"]): boolean {
  return hasType(type, "array");
}

/** What can directly follow a complete name: `.` before a record's or an
 * object's fields (or a class's constants, or Env's names), `[` before a
 * list's index, `(` after a function, a space after a keyword or operator,
 * or nothing (a literal, a plain value). */
function continuation(
  name: string,
  kind: CompletionKind,
  detail: Completion["detail"],
  binding: Context | null | undefined,
  env: string[],
): string {
  if (kind === "relationship" || kind === "constant_class") return ".";
  if (kind === "function") return "(";
  if (kind === "operator" || (kind === "keyword" && !LITERALS.includes(name))) return " ";
  if (kind === "env") return env.length ? "." : "";
  if (kind === "field") {
    if (hasType(detail, "object")) return ".";
    return hasType(detail, "array") ? "[" : "";
  }
  if (kind === "variable" && binding) {
    if (binding.kind === "namespace" || binding.node.fields) return ".";
    return binding.node.items ? "[" : "";
  }
  return "";
}

/** Whether `text` ends inside an unterminated '...'/"..." literal. */
function inString(text: string): boolean {
  let quote: string | null = null;
  let escaped = false;
  for (const char of text) {
    if (quote === null) {
      if (char === "'" || char === '"') quote = char;
    } else if (escaped) {
      escaped = false;
    } else if (char === "\\") {
      escaped = true;
    } else if (char === quote) {
      quote = null;
    }
  }
  return quote !== null;
}

type Segment = [name: string, indexes: number];

/** "a.b[0][1].c" -> [["a", 0], ["b", 2], ["c", 0]]. */
function segments(chain: string): Segment[] {
  return [...chain.matchAll(SEGMENT_RE)].map((m) => [m[1], [...m[2].matchAll(INDEX_RE)].length]);
}

// A walk's position: at a record (top level, or across a relationship), or
// inside its JSON fields.
type Context = { kind: "namespace"; namespace: string } | { kind: "field"; node: FieldNode };

type Vocabs = Record<string, Vocabulary>;

function has(obj: object, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(obj, key);
}

function step(vocabs: Vocabs, context: Context, name: string): Context | null {
  if (context.kind === "namespace") {
    const vocab = vocabs[context.namespace];
    if (has(vocab.relationships, name)) return { kind: "namespace", namespace: vocab.relationships[name] };
    if (has(vocab.fields, name)) return { kind: "field", node: vocab.fields[name] };
    if (vocab.columns.includes(name)) return { kind: "field", node: { type: vocab.column_types[name] ?? null } };
    return null;
  }
  const fields = context.node.fields ?? {};
  return has(fields, name) ? { kind: "field", node: fields[name] } : null;
}

function index(context: Context | null, count: number): Context | null {
  for (let i = 0; i < count; i++) {
    if (!context || context.kind !== "field" || !context.node.items) return null;
    context = { kind: "field", node: context.node.items };
  }
  return context;
}

/** A collection's elements as a context: undefined if `name` isn't a
 * collection of `namespace`, null for one with nothing to walk into
 * (`backlinks`, self-linked `child_refs`). */
function collectionContext(vocabs: Vocabs, namespace: string, name: string): Context | null | undefined {
  const collections = vocabs[namespace].collections;
  if (!has(collections, name)) return undefined;
  const target = collections[name];
  return target === null ? null : { kind: "namespace", namespace: target };
}

/** `step` then `index`, except that an indexed collection on a record
 * (`parent_families[0]`) steps to the record that entry links to, the way
 * a relationship does. */
function stepIndexed(vocabs: Vocabs, context: Context, name: string, indexes: number): Context | null {
  if (context.kind === "namespace" && indexes > 0) {
    const collection = collectionContext(vocabs, context.namespace, name);
    if (collection) return index(collection, indexes - 1);
  }
  return index(step(vocabs, context, name), indexes);
}

/** The collections an index can follow from a record (`families`,
 * `citations`, ...; not `backlinks` or `child_refs`). */
function indexableCollections(vocabs: Vocabs, context: Context): Candidate[] {
  if (context.kind !== "namespace") return [];
  return Object.entries(vocabs[context.namespace].collections)
    .filter(([, target]) => target !== null)
    .map(([name, target]): Candidate => [name, "collection", target]);
}

function walk(
  vocabs: Vocabs,
  root: string,
  segs: Segment[],
  bindings: Map<string, Context | null>,
  iterating = false,
): Context | null {
  if (segs.length === 0) return null;
  const [[first, firstIndexes], ...rest] = segs;
  let context: Context | null;
  if (bindings.has(first)) {
    const bound = bindings.get(first) ?? null;
    context = bound ? index(bound, firstIndexes) : null;
  } else {
    if (iterating && rest.length === 0 && firstIndexes === 0) {
      const collection = collectionContext(vocabs, root, first);
      if (collection !== undefined) return collection;
    }
    context = stepIndexed(vocabs, { kind: "namespace", namespace: root }, first, firstIndexes);
  }
  // A collection can't be reached across a relationship (mother.events) --
  // GOQL rejects that -- but an indexed one can (mother.families[0]): like a
  // relationship, it leads to the record that entry links to.
  for (const [name, indexes] of rest) {
    if (!context) return null;
    context = stepIndexed(vocabs, context, name, indexes);
  }
  if (iterating && context && context.kind === "field") return index(context, 1);
  return context;
}

const PICKED_PATH_RE = new RegExp(`\\]\\[([0-9]+)\\]((?:\\.${SEGMENT})*)$`);

/** A whole expression that is one entry of a list comprehension, read on
 * or not (`[f for f in parent_families if ...][0].mother.primary_name`):
 * the comprehension's text up to its `]`, the index, and the path after;
 * null for anything else. */
export function splitGoqlPick(text: string): { comprehension: string; index: number; rest: string } | null {
  const trimmed = text.trim();
  const m = PICKED_PATH_RE.exec(trimmed);
  if (!m || !trimmed.startsWith("[")) return null;
  const comprehension = trimmed.slice(0, m.index + 1);
  // The `]` must close the `[` the expression starts with.
  let depth = 0;
  for (let position = 0; position < comprehension.length; position++) {
    if (comprehension[position] === "[") depth += 1;
    else if (comprehension[position] === "]") {
      depth -= 1;
      if (depth === 0 && position !== comprehension.length - 1) return null;
    }
  }
  if (comprehensionEnding(comprehension) === null) return null;
  return { comprehension, index: Number(m[1]), rest: m[2] };
}

/** What a plain path (`birth.date`, `primary_name.surname_list[0]`) reaches
 * in `namespace`: a whole record (across a relationship, or the path is
 * just one), a JSON field's vocabulary node, or null when the vocabulary
 * doesn't know it. */
export function resolveGoqlPath(
  namespace: string,
  chain: string,
): { kind: "record"; namespace: string } | { kind: "field"; node: FieldNode } | null {
  if (!GOQL_VOCABULARIES[namespace]) return null;
  const pick = splitGoqlPick(chain);
  const context = pick
    ? pickedContext(GOQL_VOCABULARIES, namespace, pick.comprehension, pick.rest, bindingsIn(GOQL_VOCABULARIES, namespace, chain))
    : walk(GOQL_VOCABULARIES, namespace, segments(chain), new Map());
  if (!context) return null;
  return context.kind === "namespace" ? { kind: "record", namespace: context.namespace } : context;
}

/** Comprehension variables in `source` (`for e in events`) and what each
 * iterates over, in source order so a later one can use an earlier one. */
function bindingsIn(vocabs: Vocabs, root: string, source: string): Map<string, Context | null> {
  const bindings = new Map<string, Context | null>();
  for (const m of source.matchAll(BINDING_RE)) {
    bindings.set(m[1], walk(vocabs, root, segments(m[2]), bindings, true));
  }
  return bindings;
}

type Candidate = [name: string, kind: CompletionKind, detail: Completion["detail"]];

/** What a list comprehension ending at `text`'s final `]` collects (`a.value`
 * in `[a.value for a in attribute_list if ...]`), or null if that `]`
 * doesn't close one. */
function comprehensionEnding(text: string): string | null {
  let depth = 0;
  for (let position = text.length - 1; position >= 0; position--) {
    const char = text[position];
    if (char === "]") {
      depth += 1;
    } else if (char === "[") {
      depth -= 1;
      if (depth === 0) {
        const m = COMPREHENSION_RE.exec(text.slice(position + 1, -1));
        return m ? m[1] : null;
      }
    }
  }
  return null;
}

/** Where `[x.f for x in rel if ...][n]<rest>` leads: what the comprehension
 * collects (`text` ends at its `]`), walked on by `rest` (`.mother`). */
function pickedContext(
  vocabs: Vocabs,
  namespace: string,
  text: string,
  rest: string,
  bindings: Map<string, Context | null>,
): Context | null {
  const collected = comprehensionEnding(text);
  if (collected === null) return null;
  let context = walk(vocabs, namespace, segments(collected), bindings);
  for (const [name, indexes] of segments(rest)) {
    if (!context) return null;
    context = stepIndexed(vocabs, context, name, indexes);
  }
  return context;
}

function namesAt(vocabs: Vocabs, context: Context): Candidate[] {
  if (context.kind === "field") {
    return Object.entries(context.node.fields ?? {}).map(([name, node]) => [name, "field", node.type]);
  }
  const vocab = vocabs[context.namespace];
  // Relationships first: a name that's both (an Event's `place`) is
  // reported as the relationship, since that's what a `.` walks into.
  return [
    ...Object.entries(vocab.relationships).map(([name, target]): Candidate => [name, "relationship", target]),
    ...vocab.columns.map((name): Candidate => [name, "column", null]),
    ...Object.entries(vocab.fields).map(([name, node]): Candidate => [name, "field", node.type]),
  ];
}

// Python's str.lower() then plain code-point order, matching GOQL's own
// sort key -- localeCompare would order differently ("_" vs letters).
function compareNames(a: string, b: string): number {
  const la = a.toLowerCase();
  const lb = b.toLowerCase();
  if (la !== lb) return la < lb ? -1 : 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

export function completeFromVocabularies(
  vocabs: Vocabs,
  namespace: string,
  source: string,
  cursor: number,
  env: Iterable<string> = [],
): Completion[] {
  const before = source.slice(0, cursor);
  if (inString(before)) return [];
  const vocab = vocabs[namespace];
  if (!vocab) return [];
  const envList = [...env];
  // Env is offered only where the caller will supply values for it.
  const envNames: Candidate[] = envList.length ? [[vocab.env, "env", null]] : [];
  const partial = PARTIAL_OPERATOR_RE.exec(before);
  if (partial) {
    // A half-typed comparison (`gender <`): the operators it can become.
    const typed = partial[0];
    const start = cursor - typed.length;
    if (expected(before.slice(0, start))[0] !== "operator") return [];
    return [...vocab.operators]
      .sort()
      .filter((name) => name.startsWith(typed))
      .map((name) => ({ name: name === typed ? `${name} ` : name, kind: "operator", detail: null, start }));
  }
  const picked = PICKED_RE.exec(before);
  if (picked && comprehensionEnding(before.slice(0, picked.index + 1)) !== null) {
    // `[a for a in attribute_list if ...][0].`: the entry's own names.
    const prefix = picked[2] ?? "";
    const bindings = bindingsIn(vocabs, namespace, source);
    const context = pickedContext(vocabs, namespace, before.slice(0, picked.index + 1), picked[1], bindings);
    const candidates = context ? [...namesAt(vocabs, context), ...indexableCollections(vocabs, context)] : [];
    return results(candidates, prefix, cursor - prefix.length, bindings, envList);
  }
  if (PICK_INDEX_RE.test(before) && comprehensionEnding(before.slice(0, -1)) !== null) {
    // `[a for a in attribute_list if ...][`: which matching entry.
    return [{ name: "0", kind: "index", detail: "first item", start: cursor }];
  }
  const match = AT_CURSOR_RE.exec(before);
  if (!match) return [];
  const chain = match[1];
  const prefix = match[2] ?? "";
  const start = cursor - prefix.length;
  const bindings = bindingsIn(vocabs, namespace, source);

  let candidates: Candidate[];
  if (chain === undefined) {
    const [want, comprehension] = expected(before.slice(0, start));
    const paths: Candidate[] = [
      ...namesAt(vocabs, { kind: "namespace", namespace }),
      ...[...bindings.keys()].map((name): Candidate => [name, "variable", null]),
    ];
    const collections = Object.entries(vocab.collections).map(([name, target]): Candidate => [name, "collection", target]);
    const names = [...paths, ...collections];
    const literals = LITERALS.map((name): Candidate => [name, "keyword", null]);
    const constantClasses = Object.keys(vocab.constants).map((name): Candidate => [name, "constant_class", null]);
    const quote: Candidate = ['"', "punctuation", "text"];
    const listOpen: Candidate = ["[", "punctuation", "list"];
    const compared =
      want === "value" || want === "literal" ? comparedField(vocabs, namespace, before.slice(0, start), bindings) : null;
    const comparedType = compared?.type ?? null;
    if (compared?.constants) {
      // The field compared with holds one class's constants (`type.value
      // ==` -> `EventType.`): offer just that class.
      candidates = [[`${compared.constants.class}.`, "constant_class", null], ...envNames];
    } else if (hasType(comparedType, "boolean") && !hasType(comparedType, "string")) {
      candidates = [["True", "keyword", null], ["False", "keyword", null], ...envNames];
    } else if (hasType(comparedType, "string") && !prefix) {
      // Text is nearly always compared with a quoted string; a letter typed
      // first still gets names (`father.surname == mother.su`).
      candidates = [quote, ...envNames];
    } else if (want === "operand") {
      candidates = [...names, ...vocab.functions.map((name): Candidate => [name, "function", null]), ["not", "keyword", null], ...envNames];
    } else if (want === "value" || want === "is_value") {
      candidates = [
        ...(want === "is_value" ? [["not", "keyword", null] as Candidate] : []),
        ...literals,
        ...VALUE_FUNCTIONS.map((name): Candidate => [name, "function", null]),
        ...constantClasses,
        ...envNames,
        ...names,
      ];
    } else if (want === "operator") {
      const words = comprehension ? [...CONTINUATIONS, ...COMPREHENSION_WORDS] : CONTINUATIONS;
      candidates = words.map((name): Candidate => [name, "keyword", null]);
      if (!prefix) candidates.push(...vocab.operators.map((name): Candidate => [name, "operator", null]));
    } else if (want === "not_in") {
      candidates = [["in", "keyword", null]];
    } else if (want === "in_list") {
      candidates = [listOpen, ...envNames];
    } else if (want === "path") {
      candidates = paths;
    } else if (want === "number") {
      candidates = [...paths, ["len", "function", null], ...envNames];
    } else if (want === "string") {
      candidates = [quote];
    } else if (want === "collection") {
      candidates = collections;
    } else if (want === "iterable") {
      candidates = [...paths.filter(([, kind, detail]) => kind === "relationship" || kind === "variable" || isArray(detail)), ...collections];
      const opened = before.slice(0, start).trimEnd();
      if (opened.endsWith("distinct(")) {
        // distinct(...) only takes a list of fields: [f.father for ...].
        candidates = [listOpen];
      } else if (opened.endsWith("len(")) {
        candidates.push(listOpen);
        // Only counted so far, so offered only inside len(.
        candidates.push(["distinct", "function", null]);
      }
    } else if (want === "index") {
      candidates = [];
      const indexed = INDEXED_RE.exec(before.slice(0, start));
      if (indexed) {
        const listed = segments(indexed[1]);
        const context = walk(vocabs, namespace, listed, bindings);
        if (context && context.kind === "field" && context.node.items) {
          candidates = [["0", "index", "first item"]];
        } else if (listed[listed.length - 1][1] === 0) {
          // `parent_families[`: a collection's first entry.
          const owner: Context | null =
            listed.length > 1 ? walk(vocabs, namespace, listed.slice(0, -1), bindings) : { kind: "namespace", namespace };
          const last = listed[listed.length - 1][0];
          if (owner && indexableCollections(vocabs, owner).some(([name]) => name === last)) {
            candidates = [["0", "index", "first item"]];
          }
        }
      }
    } else if (want === "literal") {
      candidates = [quote, ...literals, ...constantClasses, ...envNames];
    } else {
      candidates = [];
    }
  } else {
    const segs = segments(chain);
    const [first, firstIndexes] = segs[0];
    const single = segs.length === 1 && firstIndexes === 0;
    if (single && !bindings.has(first) && has(vocab.constants, first)) {
      let constantNames = vocab.constants[first];
      // After `date.modifier == Date.`, only the MOD_ constants.
      const chainStart = start - chain.length - 1;
      const wanted = valueConstants(vocabs, namespace, before.slice(0, chainStart), bindings);
      if (wanted && wanted.class === first) constantNames = constantNames.filter((name) => name.startsWith(wanted.prefix));
      candidates = constantNames.map((name): Candidate => [name, "constant", first]);
    } else if (single && !bindings.has(first) && first === vocab.env) {
      candidates = envList.map((name): Candidate => [name, "env", null]);
    } else {
      // What the grammar expects where the dotted path began decides which
      // walked-to names fit: anything for a condition or value, only steps
      // toward a list for an iterable, nothing where a string, a bare
      // collection or a list literal belongs.
      const chainStart = start - chain.length - 1;
      const role = expected(before.slice(0, chainStart))[0];
      const context = walk(vocabs, namespace, segs, bindings);
      candidates = context ? namesAt(vocabs, context) : [];
      if (context && ["operand", "value", "is_value", "number"].includes(role)) {
        // `father.families[0]...`: one entry of a collection, across a hop.
        candidates = [...candidates, ...indexableCollections(vocabs, context)];
      }
      if (role === "iterable") {
        candidates = candidates.filter(([, kind, detail]) => kind === "relationship" || isArray(detail));
      } else if (!["operand", "value", "is_value", "path", "number"].includes(role)) {
        candidates = [];
      }
    }
  }

  return results(candidates, prefix, start, bindings, envList);
}

/** The candidates that complete `prefix`, as sorted completions. */
function results(
  candidates: Candidate[],
  prefix: string,
  start: number,
  bindings: Map<string, Context | null>,
  envList: string[],
): Completion[] {
  const seen = new Set<string>();
  const found: Completion[] = [];
  for (const [candidate, kind, detail] of candidates) {
    if (!candidate.startsWith(prefix)) continue;
    // Already typed in full: offer what continues it instead, so Tab shows
    // there's more (`primary_name.date` -> `date.`, `any` -> `any(`).
    // Deduplicated after this, so a name that's two things keeps both
    // continuations (`Date(` and `Date.`).
    const name =
      candidate === prefix
        ? candidate + continuation(candidate, kind, detail, bindings.get(candidate), envList)
        : candidate;
    if (seen.has(name)) continue;
    seen.add(name);
    found.push({ name, kind, detail, start });
  }
  found.sort((a, b) => compareNames(a.name, b.name));
  return found;
}

/** Completions for `source` at `cursor`, for a where_expr on GOQL type
 * `namespace` ("Person", ...). Empty for an unknown type. */
export function completeGoql(namespace: string, source: string, cursor: number, env: Iterable<string> = []): Completion[] {
  return completeFromVocabularies(GOQL_VOCABULARIES, namespace, source, cursor, env);
}

const NAMESPACE_BY_ENDPOINT_SEGMENT: Record<string, string> = {
  people: "Person",
  families: "Family",
  events: "Event",
  places: "Place",
  repositories: "Repository",
  sources: "Source",
  citations: "Citation",
  media: "Media",
  notes: "Note",
  tags: "Tag",
};

/** The GOQL type a view's `/api/<type>/query/` endpoint searches -- also
 * right for Topics/Output/Stories, which are Note/Media views under a
 * fixed filter. */
export function goqlNamespaceForEndpoint(endpoint: string): string | undefined {
  const segment = /^\/api\/([a-z]+)\//.exec(endpoint)?.[1];
  return segment ? NAMESPACE_BY_ENDPOINT_SEGMENT[segment] : undefined;
}

/** The longest prefix every name shares -- what Tab inserts when several
 * completions match. */
export function commonPrefix(names: string[]): string {
  if (names.length === 0) return "";
  let prefix = names[0];
  for (const name of names.slice(1)) {
    let i = 0;
    while (i < prefix.length && i < name.length && prefix[i] === name[i]) i++;
    prefix = prefix.slice(0, i);
  }
  return prefix;
}
